(5753652, 837413, 100393, '<td valign="top">The most interesting image in the challenge by some margin. 10.</td>', 'The most interesting image in the challenge by some margin. 10.', '2009-12-04 05:34:09.000000', NULL, 1),
(5753691, 837361, 109614, '<td valign="top">It appears the Pof(Plane of Focus) is more parallel to the camera sensor than not and thus not quite achieving that "miniature" affect common with tilt/shift shots. It''s still a great photo!</td>', 'It appears the Pof(Plane of Focus) is more parallel to the camera sensor than not and thus not quite achieving that "miniature" affect common with tilt/shift shots. It''s still a great photo!', '2009-12-04 06:37:43.000000', NULL, 1),
(5753698, 837367, 109614, '<td valign="top">Creative and different take on the challenge.</td>', 'Creative and different take on the challenge.', '2009-12-04 06:43:46.000000', NULL, 1),
(5753714, 836748, 109614, '<td valign="top">The Pof (Plane of Focus) appears very parallel to the camera sensor giving the entire picture equal focus and scale. It makes getting the "miniature" affect common with tilt/shift photos difficult to achieve.</td>', 'The Pof (Plane of Focus) appears very parallel to the camera sensor giving the entire picture equal focus and scale. It makes getting the "miniature" affect common with tilt/shift photos difficult to achieve.', '2009-12-04 06:56:39.000000', NULL, 1),
